import {FORMATS,EMPTY,newMatch,drop,nextRound,abandonRound,undo,undoCount,landingRow,syncEvents,statistics} from './engine.js';
import {getSettings,getConfig,getMatch,getEvents,write,saveMatch,remove,storageOK} from './storage.js';
import {icon,logo,boardSVG,discMarkup} from './board.js';
import {Sound} from './audio.js';
const $=s=>document.querySelector(s),app=$('#app'),modalRoot=$('#modal-root'),sound=new Sound();
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let settings=getSettings(),match=getMatch(),events=getEvents(),config=getConfig(),screen='menu',modal=null,returnFocus=null;
let hover=-1,selectedCol=3,busy=false,thinking=false,animation=null,worker=null,aiTimer=null,epoch=0,motionEpoch=0,toastTimer=null,resultSoundId=null,announceTimer=null,storageWarning=false,lastDropAt=-Infinity;
let setup={...config,names:[...config.names],colors:[...config.colors]};
if(match){events=syncEvents(events,match);write('events',events);}
function applySettings(){document.body.dataset.theme=settings.theme;document.body.dataset.reduced=String(settings.reduced);document.body.dataset.contrast=String(settings.contrast);document.querySelector('meta[name="theme-color"]').content=settings.theme==='light'?'#edf2fb':'#080d1b';sound.set(settings);}
applySettings();
const mini=(color,small='')=>`<span class="mini-disc ${color} ${settings.markers?'marker':''} ${small}" aria-hidden="true"></span>`;
const btn=(label,action,ico,type='secondary',extra='')=>`<button class="btn btn-${type}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
function header(){return `<header class="header"><button class="brand" data-action="menu" aria-label="FOUR main menu">${logo()}<div><div class="wordmark">FOUR</div><div class="brand-note">Think ahead. Connect four. Own the board.</div></div></button><nav class="header-nav" aria-label="Game navigation"><button class="nav-link" data-action="help" aria-label="How to play">${icon('help')}<span class="nav-text">How to play</span></button><button class="nav-link" data-action="stats" aria-label="Statistics">${icon('stats')}<span class="nav-text">Statistics</span></button><span class="nav-separator"></span><button class="icon-btn" data-action="sound" aria-label="${settings.sound?'Mute sound':'Enable sound'}" title="${settings.sound?'Mute sound':'Enable sound'}" aria-pressed="${settings.sound}">${icon(settings.sound?'sound':'muted')}</button><button class="icon-btn" data-action="theme" aria-label="Change theme, current theme ${settings.theme}" title="Change theme">${icon(settings.theme==='light'?'sun':settings.theme==='neon'?'bolt':'moon')}</button><button class="icon-btn" data-action="settings" aria-label="Settings" title="Settings">${icon('settings')}</button></nav></header>`;}
function footer(cls=''){return `<footer class="footer ${cls}"><span>FOUR · A little strategy. A lot of rivalry.</span><span><i class="pip"></i>Made for your next great move</span></footer>`;}
function demoBoard(){const b=Array(42).fill(-1);[[0,[1,0]],[1,[0,1,0]],[2,[1,0,1,0]],[3,[0,1,0,1,0]],[4,[1,1]],[5,[0]],[6,[1,0]]].forEach(([c,vs])=>vs.forEach((v,i)=>b[(5-i)*7+c]=v));return boardSVG({board:b,markers:true,decorative:true,lines:[],preview:false});}
function menuScreen(){return `<main class="screen"><section class="hero"><div class="hero-copy"><div class="eyebrow"><i class="pip"></i>THE CLASSIC. A NEW CONNECTION.</div><h1>READY TO<br><span>CONNECT?</span></h1><p class="hero-sub">Two players. One board.<br>Endless possibilities.</p><div class="hero-details"><span>${icon('users')}2 players</span><span>${icon('disc')}42 slots</span><span>${icon('bolt')}One winning connection</span></div></div><div class="hero-art"><div class="hero-orbit"></div><div class="hero-orbit two"></div><div class="showcase">${demoBoard()}</div><div class="art-label">${mini('red')}${mini('yellow')} YOUR NEXT MOVE MATTERS ${icon('spark')}</div></div></section><div class="section-top"><span class="section-title">CHOOSE YOUR CHALLENGE</span><button class="text-button" data-action="help">New to the game? ${icon('arrow')}</button></div><section class="mode-grid" aria-label="Game modes"><button class="mode-card primary" data-action="setup-local"><span class="mode-icon">${icon('users')}</span><span class="mode-arrow">${icon('arrow')}</span><h3>Play local 1v1</h3><p>A friend. A friendly rivalry. One device.</p></button><button class="mode-card" data-action="setup-ai"><span class="mode-icon">${icon('cpu')}</span><span class="mode-arrow">${icon('arrow')}</span><h3>Play vs computer</h3><p>Three levels. Find your match.</p></button><button class="mode-card" disabled aria-label="Online 1v1 unavailable, multiplayer server not connected"><span class="mode-icon">${icon('globe')}</span><span class="mode-badge">UNAVAILABLE</span><h3>Online 1v1</h3><p>No multiplayer server connected.</p></button></section><div class="menu-bottom">${match?btn(`Resume ${match.complete?'last match':'match'} · ${escape(match.config.names[0])} vs ${escape(match.config.names[1])}`,'resume','play','secondary'): `<p class="menu-tip">${icon('spark')}Easy to learn. Always another move to master.</p>`}<button class="text-button" data-action="stats">${icon('stats')} Your statistics ${icon('arrow')}</button></div></main>${footer()}`;}
function setupScreen(){const ai=setup.mode==='ai';return `<main class="screen setup-layout"><div class="back-row"><button data-action="menu">${icon('back')}Back to menu</button></div><div class="setup-heading"><div class="eyebrow">${icon(ai?'cpu':'users')}${ai?'A WORTHY OPPONENT':'BETTER TOGETHER'}</div><h1>Set the stage.</h1><p>${ai?'Your strategy. Their next move.':'Pick your names. Set your stakes. Make your move.'}</p></div><form id="setup-form" class="setup-card"><div class="player-fields"><div class="player-field"><div class="field-head">${mini(setup.colors[0])}${ai?'You':'Player one'}</div><label>Your name<input name="p1" autocomplete="off" maxlength="24" placeholder="Player 1" value="${escape(setup.names[0])}"></label></div><button class="swap-button" type="button" data-action="swap" aria-label="Swap player colors" title="Swap colors">${icon('swap')}</button><div class="player-field"><div class="field-head">${mini(setup.colors[1])}${ai?'Computer':'Player two'}</div><label>${ai?'Opponent':'Your name'}<input name="p2" autocomplete="off" maxlength="24" placeholder="${ai?'Computer':'Player 2'}" value="${escape(setup.names[1])}" ${ai?'readonly':''}></label></div></div>${ai?`<div class="setup-section"><div class="label-row">Computer difficulty <span>${icon('cpu')}</span></div><div class="segmented" aria-label="AI difficulty">${['easy','medium','hard'].map(d=>`<button type="button" class="${setup.difficulty===d?'selected':''}" data-action="difficulty" data-value="${d}" aria-pressed="${setup.difficulty===d}">${d[0].toUpperCase()+d.slice(1)}</button>`).join('')}</div><p class="format-note">${{easy:'A relaxed start. Random moves and occasional blocks.',medium:'An alert opponent with room for a surprise.',hard:'Thinks several moves ahead. Tough, but not unbeatable.'}[setup.difficulty]}</p></div>`:''}<div class="setup-section"><div class="label-row">Match format <span>MAKE IT A RIVALRY</span></div><div class="segmented formats" aria-label="Match format">${Object.entries(FORMATS).map(([key,f])=>`<button type="button" class="${setup.format===key?'selected':''}" data-action="format" data-value="${key}" aria-pressed="${setup.format===key}">${f.label.replace(' match','').replace(' wins','')}</button>`).join('')}</div><p class="format-note">${setup.format==='single'?'One round decides it. A draw ends the match as a tie.':`First to ${FORMATS[setup.format].target} wins takes the match. Draws do not count toward wins.`}</p></div><div class="toggle-row"><div class="toggle-copy">Alternate first player<small>Take turns opening each round. Player one starts the first.</small></div><button type="button" class="switch" role="switch" aria-label="Alternate first player" aria-checked="${setup.alternate}" data-action="alternate"></button></div><div class="setup-start"><button type="submit" class="btn btn-primary btn-wide">${icon('play')}Let's play ${icon('arrow')}</button></div><p class="setup-foot">${ai?'You can undo your last turn, including the computer’s response.':'Red or yellow. Same rules. May the best connection win.'}</p></form></main>${footer()}`;}
function playerPanel(p){const m=match,r=m.current,col=m.config.colors[p],active=busy?r.moves.at(-1)?.player===p:r.status==='playing'&&r.turn===p;const state=active?(busy?'DROPPING':thinking?'THINKING':'YOUR TURN'):(r.status==='playing'?'WAITING':r.winner===p?'ROUND WINNER':r.status==='draw'?'DRAW':'GOOD GAME');return `<aside class="game-side ${p?'right':''}"><div data-color="${col}" class="player-panel ${active?'active':''}" style="--player:var(--${col})"><div class="avatar">${mini(col)}</div><div class="player-tag">${m.config.mode==='ai'&&p===1?m.config.difficulty+' COMPUTER':`PLAYER ${p+1}`} · ${col}</div><div class="player-name" title="${escape(m.config.names[p])}">${escape(m.config.names[p])}</div><div class="player-score">${m.scores[p]}</div><div class="score-label">${m.scores[p]===1?'round won':'rounds won'}</div><div class="turn-badge"><i class="turn-light"></i>${state}</div></div><p class="side-note">${p===0?'<strong>Think one move ahead.</strong><br>Then think one more.':`<strong>${m.config.format==='single'?'One round. One winner.':`First to ${FORMATS[m.config.format].target} wins.`}</strong><br>Make every disc count.`}</p></aside>`;}
function statusText(){const m=match,r=m.current;const last=r.moves.at(-1);if(busy)return {title:`${m.config.names[last?.player??r.turn]} is dropping`,sub:'A little gravity. A little strategy.',color:m.config.colors[last?.player??r.turn]};if(r.status==='won')return{title:`${m.config.names[r.winner]} wins!`,sub:m.complete?'The match is complete. A connection worth celebrating.':'Four connected. Victory secured.',color:m.config.colors[r.winner]};if(r.status==='draw')return{title:"It's a draw!",sub:'A perfect battle. One more round?',color:null};if(thinking||m.config.mode==='ai'&&r.turn===1)return{title:`${m.config.names[1]} is thinking`,sub:'Finding the next connection…',color:m.config.colors[1]};return {title:`${m.config.names[r.turn]}'s turn`,sub:'Choose a column to drop your disc.',color:m.config.colors[r.turn]};}
function resultPanel(){if(busy||match.current.status==='playing')return'';const m=match,r=m.current,champ=m.complete&&m.champion!==null;return `<section class="result-card" aria-label="${m.complete?'Match':'Round'} result"><div class="result-eyebrow">${champ?'MATCH CHAMPION':m.complete?'MATCH COMPLETE':`ROUND ${m.roundNumber} COMPLETE`}</div><h2>${champ?`${escape(m.config.names[m.champion])} takes the match.`:r.status==='draw'?"It's a draw!":`${escape(m.config.names[r.winner])} wins!`}</h2><p>${r.status==='draw'?'A perfect battle. One more round?':'Four connected. Victory secured.'} <strong>${m.scores[0]} – ${m.scores[1]}</strong>${m.draws?` · ${m.draws} ${m.draws===1?'draw':'draws'}`:''}</p><div class="result-actions">${btn(m.complete?'Play again':'Next round',m.complete?'rematch':'next','arrow','primary')}${btn('Undo','undo','undo','secondary',undoCount(m)?'':'disabled')}${btn('Main menu','menu',null,'ghost')}</div>${settings.reduced?'':`<div class="confetti" aria-hidden="true">${Array.from({length:r.status==='won'?24:0},(_,i)=>`<i style="left:${5+i*3.9}%;background:var(--${i%3===0?'blue':m.config.colors[r.winner]});--dx:${(i%2?1:-1)*(20+i*4)}px;--rot:${100+i*35}deg;animation-delay:${i%5*.065}s"></i>`).join('')}</div>`}</section>`;}
function gameScreen(){const m=match,r=m.current,s=statusText(),allow=!busy&&!thinking&&r.status==='playing'&&(m.config.mode!=='ai'||r.turn===0);return `<main class="screen game-screen"><div class="game-topbar"><button class="text-button" data-action="menu">${icon('back')}Main menu</button><div class="match-meta"><span>${m.config.mode==='local'?'Local 1v1':`${m.config.difficulty} computer`}</span><span class="dot"></span><span>${FORMATS[m.config.format].label}</span><span class="dot"></span><span>Round ${m.roundNumber}</span></div></div><div class="game-layout">${playerPanel(0)}<div class="game-center"><div class="turn-status"><h1>${s.color?mini(s.color):icon('disc')}<span>${escape(s.title)}</span>${thinking?'<span class="thinking" aria-hidden="true"><i></i><i></i><i></i></span>':''}</h1><p>${s.sub}</p></div><div class="board-wrap" id="board-wrap">${boardSVG({board:r.board,colors:m.config.colors,lines:busy?[]:r.lines,markers:settings.markers,winLine:settings.winLine,active:r.turn,hover,preview:allow&&settings.preview,fallIndex:busy?r.moves.at(-1).row*7+r.moves.at(-1).col:-1})}<div class="column-controls" role="group" aria-label="Choose a column. Use left and right arrows, then Enter to drop.">${Array.from({length:7},(_,c)=>{const row=landingRow(r.board,c);return `<button class="column-button ${row<0?'full':''}" data-col="${c}" data-action="drop" tabindex="${c===selectedCol?0:-1}" aria-disabled="${!allow||row<0}" aria-label="Column ${c+1}${row<0?', full':`, ${row+1} empty slots`}"><span class="sr-only">${r.board.filter((v,i)=>i%7===c).map((v,i)=>`Row ${i+1}: ${v<0?'empty':m.config.colors[v]}`).join('. ')}</span></button>`;}).join('')}</div></div><div class="column-numbers" aria-hidden="true">${Array.from({length:7},(_,c)=>`<span class="${c===hover?'selected':''}">${landingRow(r.board,c)<0?'×':c+1}</span>`).join('')}</div>${resultPanel()}<div class="board-controls">${btn('Undo','undo','undo','ghost',busy||!undoCount(m)?'disabled':'')}${btn('New round','new-round','play','ghost',m.complete||(!r.moves.length&&r.status==='playing')?'disabled':'')}${btn('Restart match','restart','restart','ghost')}<button class="icon-btn" data-action="pause" aria-label="Pause game" title="Pause game">${icon('pause')}</button></div><div class="game-summary"><span>${r.moves.length} / 42 moves</span><span>${m.draws} ${m.draws===1?'draw':'draws'}</span>${m.rounds.length?`<div class="history-dots" aria-label="Completed rounds">${m.rounds.slice(-30).map((x,i)=>`<span class="history-dot ${x.winner===null?'':m.config.colors[x.winner]}" title="Round ${Math.max(0,m.rounds.length-30)+i+1}: ${x.winner===null?'Draw':escape(m.config.names[x.winner])+' won'}"></span>`).join('')}</div>`:''}<span>${m.config.alternate?'Alternating starts':'Player one starts'}</span></div>${settings.keyboard?`<div class="keyboard-hint">${icon('keyboard')}<kbd>←</kbd><kbd>→</kbd> select <kbd>Enter</kbd> drop <kbd>Esc</kbd> pause</div>`:''}</div>${playerPanel(1)}</div></main>${footer('game-footer')}`;}
function statsScreen(){const s=statistics(events);return `<main class="screen"><div class="back-row"><button data-action="${match&&screen==='stats'&&statsReturn==='game'?'back-game':'menu'}">${icon('back')}Back to ${statsReturn==='game'?'game':'menu'}</button></div><div class="stats-heading"><div class="eyebrow" style="margin-bottom:15px">YOUR NEXT PERSONAL BEST</div><h1>Every move tells a story.</h1><p>Your record on this device. The wins, the close calls, the connections.</p></div><div class="stats-grid">${[['disc',s.rounds,'Completed rounds'],['trophy',s.matches,'Completed matches'],['bolt',s.longest,'Longest color win streak'],['flag',s.average,'Average moves / round']].map(([ico,n,t])=>`<div class="stat-tile">${icon(ico)}<strong>${n}</strong><span>${t}</span></div>`).join('')}</div><div class="stats-bottom"><section class="stat-card"><h3>The color of victory</h3><div class="distribution" role="img" aria-label="${s.red} red wins, ${s.yellow} yellow wins, ${s.draws} draws">${[['red',s.red],['yellow',s.yellow],['draw',s.draws]].map(([c,n])=>`<span class="${c}" style="width:${s.rounds?n/s.rounds*100:0}%"></span>`).join('')}</div><div class="legend">${[['red',s.red,'Red'],['yellow',s.yellow,'Yellow'],['muted',s.draws,'Draws']].map(([c,n,label])=>`<div class="legend-item"><i class="legend-dot" style="background:var(--${c})"></i>${label} <b>${n}</b></div>`).join('')}</div>${!s.rounds?'<p class="empty-stats">A clean slate. Finish your first round to start your story.</p>':''}</section><section class="stat-card"><h3>Worth remembering</h3><div class="record-row"><span>Fastest victory</span><strong>${s.fastest}${s.fastest==='—'?'':' moves'}</strong></div><div class="record-row"><span>Longest consecutive color wins</span><strong>${s.longest}</strong></div><div class="record-row"><span>Drawn rounds</span><strong>${s.draws}</strong></div></section></div><div class="stats-actions"><p>Stored in this browser only. Unfinished rounds are excluded. Undo reverses the affected result.</p>${btn('Reset statistics','reset-stats','restart','ghost',events.length?'':'disabled')}</div></main>${footer()}`;}
let statsReturn='menu';
function render({focus=false}={}){applySettings();const before=document.activeElement;const a=before?.dataset?.action;app.innerHTML=`<div class="shell">${header()}${screen==='menu'?menuScreen():screen==='setup'?setupScreen():screen==='stats'?statsScreen():gameScreen()}</div>`;if(focus){const heading=$('main h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}else if(a==='drop'&&screen==='game')$(`[data-col="${selectedCol}"]`)?.focus({preventScroll:true});if(!busy&&screen==='game'&&!modal)scheduleAI();}
function persist(){if(!match)return;saveMatch(match);events=syncEvents(events,match);write('events',events);if(!storageOK&&!storageWarning){storageWarning=true;toast('Browser storage is unavailable. This game will stay in memory.');}}
function announce(text){clearTimeout(announceTimer);$('#announcer').textContent='';announceTimer=setTimeout(()=>$('#announcer').textContent=text,30);}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3300);}
function captureSetup(){const form=$('#setup-form');if(form)setup.names=[form.elements.p1.value,form.elements.p2.value];}
function navigate(to){if(screen==='setup')captureSetup();if(to!=='game')stopAI();screen=to;hover=-1;render({focus:true});window.scrollTo({top:0,behavior:'instant'});sound.play('menu');}
function stopAI(){epoch++;clearTimeout(aiTimer);aiTimer=null;if(worker){worker.terminate();worker=null;}thinking=false;}
function cancelActivity(){motionEpoch++;stopAI();if(animation){animation.onfinish=null;animation.cancel();animation=null;}busy=false;}
function start(config){cancelActivity();lastDropAt=-Infinity;match=newMatch(config);setup={...match.config,names:[...match.config.names],colors:[...match.config.colors]};write('config',match.config);config=match.config;persist();screen='game';hover=-1;resultSoundId=null;render({focus:true});window.scrollTo({top:0,behavior:'instant'});sound.play('menu');announce(`${match.config.names[0]} starts. Choose a column.`);}
function canDrop(){return screen==='game'&&match&&!modal&&!busy&&!thinking&&!match.complete&&match.current.status==='playing'&&(match.config.mode!=='ai'||match.current.turn===0);}
function makeMove(col,computer=false){if(!computer&&(!canDrop()||performance.now()-lastDropAt<200))return;const before=match,after=drop(match,col);if(before===after){sound.play('invalid');const b=$('#board-wrap');b?.classList.add('invalid');setTimeout(()=>b?.classList.remove('invalid'),250);toast('That column is full. Choose another.');return;}lastDropAt=performance.now();stopAI();match=after;busy=true;selectedCol=col;hover=-1;persist();const move=match.current.moves.at(-1),token=motionEpoch;render();sound.play('drop');const el=$('#falling-disc'),distance=24-(120+move.row*100),base=310+move.row*28,factor={fast:.65,normal:1,slow:1.5}[settings.speed];let finished=false;const settle=()=>{if(finished||token!==motionEpoch)return;finished=true;animation=null;busy=false;sound.play('land');render();const r=match.current;announce(`${match.config.names[move.player]} placed ${match.config.colors[move.player]} in column ${col+1}, row ${move.row+1}. ${r.status==='playing'?`${match.config.names[r.turn]}'s turn.`:r.status==='won'?`${match.config.names[r.winner]} wins. Score ${match.scores[0]} to ${match.scores[1]}.`:'The round is a draw.'}`);if(r.status!=='playing'&&resultSoundId!==r.id){resultSoundId=r.id;sound.play(r.status==='draw'?'draw':match.complete?'champion':'win');}else if(r.status==='playing')sound.play('turn');};if(settings.reduced||!el){queueMicrotask(settle);return;}animation=el.animate([{transform:`translateY(${distance}px)`,offset:0,easing:'cubic-bezier(.42,0,1,.7)'},{transform:'translateY(0)',offset:.78,easing:'ease-out'},{transform:'translateY(-9px)',offset:.9,easing:'ease-in'},{transform:'translateY(0)',offset:1}],{duration:base*factor,fill:'both'});animation.onfinish=settle;if(modal)animation.pause();}
function scheduleAI(){if(screen!=='game'||!match||modal||busy||thinking||match.complete||match.current.status!=='playing'||match.config.mode!=='ai'||match.current.turn!==1)return;thinking=true;const token=++epoch,startTime=performance.now();const aiId=match.current.id,moveCount=match.current.moves.length;updateTurnOnly();const complete=col=>{const wait=Math.max(0,360-(performance.now()-startTime));aiTimer=setTimeout(()=>{aiTimer=null;if(epoch!==token||modal||screen!=='game'||match.current.id!==aiId||match.current.moves.length!==moveCount||match.current.turn!==1||match.current.status!=='playing')return;thinking=false;worker?.terminate();worker=null;makeMove(col,true);},wait);};const fallback=()=>{import('./ai.js').then(({chooseMove})=>{if(epoch===token)complete(chooseMove(match.current.board,1,'medium',{budget:35,depth:2}));});toast('Computer fallback enabled for this browser.');};try{worker=new Worker(new URL('./ai-worker.js',import.meta.url),{type:'module'});worker.onmessage=e=>{if(epoch!==token)return;if(e.data.error){worker.terminate();worker=null;fallback();}else if(e.data.id===token)complete(e.data.col);};worker.onerror=()=>{worker?.terminate();worker=null;if(epoch===token)fallback();};worker.postMessage({board:match.current.board,player:1,difficulty:match.config.difficulty,id:token});}catch{fallback();}}
function updateTurnOnly(){const e=$('.turn-status');if(!e)return;const s=statusText();e.innerHTML=`<h1>${s.color?mini(s.color):''}<span>${escape(s.title)}</span>${thinking?'<span class="thinking" aria-hidden="true"><i></i><i></i><i></i></span>':''}</h1><p>${s.sub}</p>`;const badge=$('.player-panel.active .turn-badge');if(badge)badge.innerHTML=`<i class="turn-light"></i>${thinking?'THINKING':busy?'DROPPING':'YOUR TURN'}`;}
function updatePreview(col){hover=col;if(!canDrop()||!settings.preview)return;const b=match.current.board,row=landingRow(b,col),x=70+col*100,color=match.config.colors[match.current.turn];const p=$('#preview-layer'),top=$('#top-preview'),glow=$('#column-glow');if(!p||!top||!glow)return;p.innerHTML=row>=0?`<g opacity=".27">${discMarkup(x,120+row*100,color,null,settings.markers)}</g>`:'';top.innerHTML=row>=0?`<g opacity=".85" transform="translate(${x} 25) scale(.55) translate(${-x} -25)">${discMarkup(x,25,color,null,settings.markers)}</g>`:col>=0?`<path d="M${x-7} 18l14 14m0-14-14 14" stroke="#96a4c0" stroke-width="3" stroke-linecap="round"/>`:'';glow.innerHTML=row>=0?`<rect x="${23+col*100}" y="73" width="94" height="594" rx="25" fill="white" opacity=".055"/>`:'';document.querySelectorAll('.column-numbers span').forEach((e,i)=>e.classList.toggle('selected',i===col));}
function doUndo(){if(!match||busy||!undoCount(match))return;stopAI();match=undo(match);resultSoundId=null;persist();hover=-1;render();sound.play('click');announce(`Move undone. ${match.config.names[match.current.turn]}'s turn.`);}
function next(){cancelActivity();match=nextRound(match);resultSoundId=null;persist();hover=-1;render();sound.play('menu');announce(`Round ${match.roundNumber}. ${match.config.names[match.current.turn]} starts.`);}
function openModal(type,opts={}){returnFocus=document.activeElement;if(screen==='game'){if(animation)animation.pause();stopAI();updateTurnOnly();}modal={type,...opts};app.inert=true;renderModal();sound.play('click');requestAnimationFrame(()=>modalRoot.querySelector('button,input,select')?.focus({preventScroll:true}));}
function closeModal(){modal=null;app.inert=false;modalRoot.innerHTML='';if(animation)animation.play();else if(screen==='game'){if(!busy)render();scheduleAI();}if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});else if(screen==='game')$(`[data-col="${selectedCol}"]`)?.focus({preventScroll:true});}
const toggle=(key,title,description)=>`<div class="toggle-row"><div class="toggle-copy">${title}${description?`<small>${description}</small>`:''}</div><button class="switch" role="switch" aria-label="${title}" aria-checked="${settings[key]}" data-action="setting" data-key="${key}"></button></div>`;
function settingsContent(){return `<section><div class="section-title">APPEARANCE</div><div class="theme-options" style="margin-top:13px">${[['dark','moon','Dark'],['light','sun','Light'],['neon','bolt','Arcade neon']].map(([key,ico,name])=>`<button class="theme-option ${settings.theme===key?'selected':''}" data-action="set-theme" data-value="${key}" aria-pressed="${settings.theme===key}">${icon(ico)}${name}</button>`).join('')}</div></section><section class="modal-section"><div class="section-title">AUDIO</div>${toggle('sound','Sound effects','Original, gently synthesized game sounds.')}<label class="range-row">Volume <input type="range" min="0" max="100" value="${Math.round(settings.volume*100)}" data-setting="volume" aria-label="Sound volume"><span id="volume-value">${Math.round(settings.volume*100)}%</span></label></section><section class="modal-section"><div class="section-title">GAMEPLAY</div><div class="toggle-row"><div class="toggle-copy">Disc animation speed</div><select class="setting-select" aria-label="Disc animation speed" data-setting="speed">${['slow','normal','fast'].map(v=>`<option ${v===settings.speed?'selected':''}>${v}</option>`).join('')}</select></div>${toggle('preview','Show move preview','See where your disc will land.')}${toggle('winLine','Winning connection line')}${toggle('confirmRestart','Confirm match restart','Ask before clearing a match in progress.')}</section><section class="modal-section"><div class="section-title">ACCESSIBILITY</div>${toggle('reduced','Reduced motion','Instant disc placement and minimal animation.')}${toggle('contrast','High contrast')}${toggle('markers','Disc symbols','Red uses a dot; yellow uses a diamond.')}${toggle('keyboard','Keyboard controls','← → choose a column · Enter or Space drops.')}</section><p class="settings-note">Preferences are saved on this device.</p>`;}
function helpContent(){const diagrams=[['Horizontal',[12,13,14,15]],['Vertical',[2,6,10,14]],['Diagonal',[12,9,6,3]]];return `<p class="modal-copy">Two players. One simple goal: connect four of your discs before your opponent does.</p><div class="help-grid">${diagrams.map(([title,cells])=>`<div class="help-tile"><svg viewBox="0 0 120 120" aria-label="${title} winning example">${Array.from({length:16},(_,i)=>`<circle cx="${15+i%4*30}" cy="${15+Math.floor(i/4)*30}" r="10" fill="${cells.includes(i)?'#ff5268':'#254376'}"/>`).join('')}<path d="M${15+cells[0]%4*30} ${15+Math.floor(cells[0]/4)*30}L${15+cells[3]%4*30} ${15+Math.floor(cells[3]/4)*30}" stroke="#fff" stroke-width="2" stroke-linecap="round"/></svg><span>${title}</span></div>`).join('')}</div><div class="rule-list">${[['Take turns','Player one starts. Choose any column that has space.'],['Let gravity do its thing','Your disc drops into the lowest empty slot.'],['Make the connection','Four in a row wins: across, down, or either diagonal.'],['Fill the board? Call it even.','If all 42 slots fill without a winner, the round is a draw.']].map(([title,text],i)=>`<div class="rule-item"><div class="rule-number">0${i+1}</div><div><strong>${title}</strong>${text}</div></div>`).join('')}</div><div class="help-note"><strong>Series:</strong> First to the required wins takes the match. Draws don’t award wins.<br><strong>Undo:</strong> Unlimited within the current round. Against the computer, your move and its response are undone together. Completed rounds can be undone until you continue.<br><strong>Keyboard:</strong> Focus the board, then use ← → and Enter or Space. Escape pauses.</div><div class="modal-actions">${btn(screen==='game'?'Back to game':'Start a game',screen==='game'?'close-modal':'help-start','arrow','primary')}</div>`;}
function renderModal(){if(!modal)return;let title='',body='',wide=false;if(modal.type==='settings'){title='Make it yours.';body=settingsContent();}else if(modal.type==='help'){title='Four is all it takes.';body=helpContent();wide=true;}else if(modal.type==='pause'){title='Take your time.';body=`<div class="paused"><div class="pause-symbol">${icon('pause')}</div><h3>Game paused.</h3><p>A good next move is worth the wait. Your board is right where you left it.</p>${btn('Resume game','close-modal','play','primary')}</div>`;}else{title=modal.title;body=`<p class="modal-copy">${modal.copy}</p><div class="modal-actions">${btn('Cancel','close-modal',null,'ghost')}${btn(modal.label??'Confirm','confirm-action',modal.ico??null,modal.danger?'danger':'primary')}</div>`;}modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${body}</section></div>`;}
function refreshSetting(key){applySettings();write('settings',settings);if(!busy)render();else{const h=$('.header');if(h)h.outerHTML=header();}const focused=modalRoot.querySelector(':focus');const action=focused?.dataset?.action,k=focused?.dataset?.key,v=focused?.dataset?.value;renderModal();if(action)modalRoot.querySelector(`[data-action="${action}"]${k?`[data-key="${k}"]`:''}${v?`[data-value="${v}"]`:''}`)?.focus({preventScroll:true});}
function requestMenu(){if(screen!=='game'||!match){navigate('menu');return;}if(match.complete){cancelActivity();navigate('menu');return;}openModal('confirm',{title:'Leave the table?',copy:'Your match is saved on this device. You can pick up exactly where you left off from the main menu.',label:'Save & exit',ico:'back',onConfirm:()=>{cancelActivity();persist();navigate('menu');}});}
function requestRestart(){if(!match)return;const run=()=>start(match.config);if(match.complete||!match.current.moves.length&&!match.rounds.length||!settings.confirmRestart){run();return;}openModal('confirm',{title:'Restart this match?',copy:'The board and match score will start from zero. Completed rounds stay in your device statistics.',label:'Restart match',ico:'restart',danger:true,onConfirm:run});}
function requestNewRound(){if(!match||match.complete)return;if(match.current.status!=='playing'){next();return;}openModal('confirm',{title:'Start this round over?',copy:'This unfinished round will be discarded. Your match score stays the same, and this round will not enter your statistics.',label:'Start fresh',ico:'play',onConfirm:()=>{cancelActivity();match=abandonRound(match);persist();hover=-1;render();announce('Round restarted. Scores are unchanged.');}});}
function goSetup(mode){const run=()=>{setup={...getConfig(),mode,names:[getConfig().names[0],mode==='ai'?'Computer':getConfig().mode==='ai'?'Player 2':getConfig().names[1]],colors:[...getConfig().colors]};navigate('setup');};if(match&&!match.complete&&(match.rounds.length||match.current.moves.length))openModal('confirm',{title:'Start a new matchup?',copy:'Your saved match will be replaced when you press Let’s play. Completed rounds will remain in your statistics.',label:'Set up new match',onConfirm:run});else run();}
function resetStatistics(){openModal('confirm',{title:'Reset device statistics?',copy:'This clears your completed rounds, match totals, and records on this device. Your current match will also be cleared so its old results cannot be counted again.',label:'Reset statistics',danger:true,onConfirm:()=>{cancelActivity();events=[];match=null;write('events',events);remove('match');statsReturn='menu';render();toast('Statistics reset. A fresh start.');}});}
function dispatch(action,el){sound.unlock();if(!['drop','sound','setting','set-theme','close-modal'].includes(action))sound.play('click');switch(action){case'menu':requestMenu();break;case'setup-local':goSetup('local');break;case'setup-ai':goSetup('ai');break;case'help':openModal('help');break;case'help-start':closeModal();goSetup('local');break;case'settings':openModal('settings');break;case'pause':openModal('pause');break;case'close-modal':closeModal();break;case'confirm-action':{const fn=modal?.onConfirm;modal=null;app.inert=false;modalRoot.innerHTML='';fn?.();break;}case'sound':settings.sound=!settings.sound;applySettings();write('settings',settings);if(!busy)render();else $('.header').outerHTML=header();if(settings.sound)sound.play('click');break;case'theme':{const ts=['dark','light','neon'];settings.theme=ts[(ts.indexOf(settings.theme)+1)%3];applySettings();write('settings',settings);if(!busy)render();else $('.header').outerHTML=header();toast(`${settings.theme==='neon'?'Arcade neon':settings.theme[0].toUpperCase()+settings.theme.slice(1)} theme`);break;}case'stats':statsReturn=screen==='game'?'game':'menu';if(screen==='game'){if(animation)animation.finish();cancelActivity();}navigate('stats');break;case'back-game':case'resume':screen='game';hover=-1;render({focus:true});window.scrollTo({top:0,behavior:'instant'});sound.play('menu');break;case'swap':captureSetup();setup.colors.reverse();render();$('[data-action="swap"]')?.focus();break;case'format':captureSetup();setup.format=el.dataset.value;render();$(`[data-action="format"][data-value="${setup.format}"]`)?.focus();break;case'difficulty':captureSetup();setup.difficulty=el.dataset.value;render();$(`[data-action="difficulty"][data-value="${setup.difficulty}"]`)?.focus();break;case'alternate':captureSetup();setup.alternate=!setup.alternate;render();$('[data-action="alternate"]')?.focus();break;case'drop':makeMove(Number(el.dataset.col));break;case'undo':doUndo();break;case'next':next();break;case'rematch':start(match.config);break;case'restart':requestRestart();break;case'new-round':requestNewRound();break;case'reset-stats':resetStatistics();break;case'setting':settings[el.dataset.key]=!settings[el.dataset.key];refreshSetting(el.dataset.key);break;case'set-theme':settings.theme=el.dataset.value;refreshSetting('theme');break;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;if(modal&&!modalRoot.contains(el))return;dispatch(el.dataset.action,el);});
document.addEventListener('submit',e=>{if(e.target.id==='setup-form'){e.preventDefault();sound.unlock();captureSetup();start(setup);}});
document.addEventListener('input',e=>{if(e.target.dataset.setting==='volume'){settings.volume=Number(e.target.value)/100;applySettings();write('settings',settings);$('#volume-value').textContent=`${e.target.value}%`;}if(e.target.closest('#setup-form'))captureSetup();});
document.addEventListener('change',e=>{if(e.target.dataset.setting==='speed'){settings.speed=e.target.value;write('settings',settings);}});
document.addEventListener('pointerover',e=>{const col=e.target.closest('[data-col]');if(col&&e.pointerType!=='touch')updatePreview(Number(col.dataset.col));});
document.addEventListener('pointerout',e=>{if(e.target.closest('.column-controls')&&!e.relatedTarget?.closest?.('.column-controls'))updatePreview(-1);});
document.addEventListener('focusin',e=>{if(e.target.dataset.col!==undefined){selectedCol=Number(e.target.dataset.col);updatePreview(selectedCol);}});
document.addEventListener('keydown',e=>{if(modal){if(e.key==='Escape'){e.preventDefault();closeModal();return;}if(e.key==='Tab'){const focusables=[...modalRoot.querySelectorAll('button:not(:disabled),input,select,[tabindex="0"]')];const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}return;}if(screen!=='game')return;if(e.key==='Escape'){e.preventDefault();openModal('pause');return;}if(!settings.keyboard||e.target.matches('input,select,textarea'))return;const onBoard=e.target.closest('.column-controls')||e.target===document.body||e.target.matches('.turn-status h1');if(!onBoard)return;if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();selectedCol=e.key==='Home'?0:e.key==='End'?6:(selectedCol+(e.key==='ArrowRight'?1:6))%7;document.querySelectorAll('[data-col]').forEach((el,c)=>el.tabIndex=c===selectedCol?0:-1);$(`[data-col="${selectedCol}"]`)?.focus();updatePreview(selectedCol);}else if(e.key==='Enter'||e.key===' '){e.preventDefault();if(!e.repeat){sound.unlock();makeMove(selectedCol);}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&screen==='game'&&!modal){sound.stop();openModal('pause');}});
window.addEventListener('pagehide',()=>{stopAI();sound.stop();});
// Every committed move is saved immediately; animation is never used as saved state.
render();
